// The sound of a race car, synthesised in the browser. No recordings: every
// sound here is generated by this file from oscillators and filtered noise, so
// nothing is downloaded and nothing is borrowed from any other game.
//
// One RaceSound is one race: the player's engine (firing note, half-order
// rumble, induction, turbo, overrun crackle), the road and the wind, up to two
// nearby rivals, and the one-off sounds of a race (gear change, tyre scrub,
// a car going past, the finish line). All of it is drawn from engine-model.js,
// which follows the car's real race speed.
//
// Every continuous sound is a node that lives for the whole race and is only
// ever steered with smooth parameter ramps: nothing is restarted, so there is
// nothing to click, stack up or leak. `stop()` fades out and releases it all.

import { RIVAL_VOICES, createEngineModel, engineProfile, rivalMix } from "./engine-model.js";

const SMOOTH = 0.035; // seconds: parameter ramps, short enough to follow the car, long enough never to click
const NOISE_SECONDS = 2;
const MAX_ONE_SHOTS = 5;

/** Levels of the layers, before the race gain. Tuned by ear-equivalent measurement in the audio audit. */
export const MIX = Object.freeze({
  engineIdle: 0.42,
  engineFull: 1,
  chug: 1.3,
  intake: 0.22,
  road: 0.34,
  wind: 0.07,
  turbo: 0.05,
  rival: 1,
  shift: 0.3,
  scrub: 1.2,
  pass: 1.8,
  blowOff: 1,
  crackle: 1,
  finish: 1.6
});

const noiseBuffers = new WeakMap();

/** One two-second noise buffer per audio context, shared by every layer and every race. */
export function sharedNoise(context) {
  let buffer = noiseBuffers.get(context);
  if (!buffer) {
    const length = Math.floor(context.sampleRate * NOISE_SECONDS);
    buffer = context.createBuffer(1, length, context.sampleRate);
    const data = buffer.getChannelData(0);
    // A fixed generator: the same noise every time, so a render is repeatable.
    let state = 0x2f6e2b1;
    for (let index = 0; index < length; index += 1) {
      state ^= state << 13;
      state ^= state >>> 17;
      state ^= state << 5;
      data[index] = ((state >>> 0) / 0xffffffff) * 2 - 1;
    }
    noiseBuffers.set(context, buffer);
  }
  return buffer;
}

function softClipCurve(grit) {
  const drive = 1 + grit * 7;
  const curve = new Float32Array(1024);
  const scale = Math.tanh(drive);
  for (let index = 0; index < curve.length; index += 1) {
    const x = (index / (curve.length - 1)) * 2 - 1;
    curve[index] = Math.tanh(drive * x) / scale;
  }
  return curve;
}

const WAVE_HARMONICS = 28;

/**
 * The engine's note as a waveform: the profile's first harmonics as given,
 * then a tail that dies away at the profile's own rate. The tail is what an
 * idling engine is heard by on a small speaker, where the firing note itself
 * is too low to hear; the tone filter opens and closes over it.
 */
function harmonicWave(context, harmonics, tail = 0) {
  const real = new Float32Array(WAVE_HARMONICS + 1);
  const imag = new Float32Array(WAVE_HARMONICS + 1);
  let level = 0;
  for (let index = 0; index < WAVE_HARMONICS; index += 1) {
    level = index < harmonics.length ? harmonics[index] : level * tail;
    imag[index + 1] = level;
  }
  return context.createPeriodicWave(real, imag);
}

export class RaceSound {
  /**
   * `output` is where the race is mixed to (the game's effects bus). `level`
   * scales the whole race. `random` is only used for the timing of crackles.
   */
  constructor(context, output, carKey, { level = 1, random = Math.random } = {}) {
    this.context = context;
    this.profile = engineProfile(carKey);
    this.model = createEngineModel(this.profile);
    this.random = random;
    this.stopped = false;
    this.oneShots = 0;
    this.lastFrame = null;
    this.startedAt = context.currentTime;
    this.noise = sharedNoise(context);
    this.sources = [];
    const now = context.currentTime;
    const profile = this.profile;

    // Everything in the race meets here; the race fades in so the first frame cannot click.
    this.bus = context.createGain();
    this.bus.gain.setValueAtTime(0.0001, now);
    this.bus.gain.setTargetAtTime(level, now, 0.12);
    this.bus.connect(output);

    // --- the engine --------------------------------------------------------
    const wave = harmonicWave(context, profile.harmonics, profile.tail);
    const subWave = harmonicWave(context, [1, 0.35, 0.12]);
    this.main = this.oscillator(wave);
    this.twin = this.oscillator(wave); // a hair sharp of the main note: the thickness of a real engine
    this.sub = this.oscillator(subWave);
    this.mainGain = this.gain(0.62);
    this.twinGain = this.gain(0.38);
    this.subGain = this.gain(profile.sub);
    this.shaper = context.createWaveShaper();
    this.shaper.curve = softClipCurve(profile.grit);
    this.shaper.oversample = "2x";
    this.tone = context.createBiquadFilter();
    this.tone.type = "lowpass";
    this.tone.Q.value = 0.7;
    this.tone.frequency.value = profile.dark;
    this.formant = context.createBiquadFilter();
    this.formant.type = "peaking";
    this.formant.frequency.value = profile.formant;
    this.formant.Q.value = 1.1;
    this.formant.gain.value = 6;
    this.body = this.filter("highpass", profile.body, 0.7);
    this.engineGain = this.gain(0.0001);
    this.main.connect(this.mainGain).connect(this.shaper);
    this.twin.connect(this.twinGain).connect(this.shaper);
    this.sub.connect(this.subGain).connect(this.shaper);
    this.shaper.connect(this.tone).connect(this.formant).connect(this.body).connect(this.engineGain).connect(this.bus);

    // --- induction, road and wind: three filters over the one noise loop ----
    this.intakeFilter = this.filter("bandpass", 700, 0.8);
    this.intakeGain = this.gain(0.0001);
    this.roadFilter = this.filter("lowpass", 260, 0.5);
    this.roadGain = this.gain(0.0001);
    this.windFilter = this.filter("bandpass", 1700, 0.4);
    this.windGain = this.gain(0.0001);
    // The patter of an idling exhaust: noise let through in time with the firing
    // note. It is what an idle is heard by on a phone, and it is gone by mid revs.
    this.chugFilter = this.filter("bandpass", 520, 0.7);
    this.chugGain = this.gain(0);
    this.chugDepth = this.gain(0);
    this.main.connect(this.chugDepth).connect(this.chugGain.gain);
    const loop = this.noiseLoop();
    loop.connect(this.chugFilter).connect(this.chugGain).connect(this.bus);
    loop.connect(this.intakeFilter).connect(this.intakeGain).connect(this.bus);
    loop.connect(this.roadFilter).connect(this.roadGain).connect(this.bus);
    loop.connect(this.windFilter).connect(this.windGain).connect(this.bus);

    // --- turbocharger whistle (Turbo Sprint only) ---------------------------
    if (profile.turbo > 0) {
      this.whistle = this.oscillator("sine");
      this.whistle.frequency.value = 2400;
      this.whistleGain = this.gain(0.0001);
      this.whistle.connect(this.whistleGain).connect(this.bus);
    }

    // --- up to two nearby rivals ---------------------------------------------
    this.rivals = Array.from({ length: RIVAL_VOICES }, () => {
      const oscillator = this.oscillator("sawtooth");
      oscillator.frequency.value = 60;
      const filter = this.filter("lowpass", 700, 0.6);
      const gain = this.gain(0.0001);
      const pan = typeof context.createStereoPanner === "function" ? context.createStereoPanner() : null;
      oscillator.connect(filter).connect(gain);
      if (pan) gain.connect(pan).connect(this.bus);
      else gain.connect(this.bus);
      return { oscillator, filter, gain, pan, id: null };
    });

    for (const source of this.sources) source.start(now);
  }

  oscillator(type) {
    const oscillator = this.context.createOscillator();
    if (typeof type === "string") oscillator.type = type;
    else oscillator.setPeriodicWave(type);
    this.sources.push(oscillator);
    return oscillator;
  }

  gain(value) {
    const gain = this.context.createGain();
    gain.gain.value = value;
    return gain;
  }

  filter(type, frequency, q) {
    const filter = this.context.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = frequency;
    filter.Q.value = q;
    return filter;
  }

  noiseLoop() {
    const source = this.context.createBufferSource();
    source.buffer = this.noise;
    source.loop = true;
    this.sources.push(source);
    return source;
  }

  set(param, value, tau = SMOOTH) {
    param.setTargetAtTime(value, this.context.currentTime, tau);
  }

  setLevel(level) {
    if (!this.stopped) this.set(this.bus.gain, level, 0.08);
  }

  /** A correct answer: the throttle opens. */
  boost() {
    if (!this.stopped) this.model.boost();
  }

  /** A wrong answer: the throttle shuts and the tyres scrub. Nothing accelerates. */
  lift() {
    if (this.stopped) return;
    const share = this.lastFrame?.speedShare ?? 0;
    this.model.lift();
    if (share > 0.08) this.burst({ type: "bandpass", from: 1500, to: 900, q: 1.6, level: MIX.scrub * Math.min(1, 0.35 + share), attack: 0.02, seconds: 0.42 });
  }

  /**
   * Once a frame. `player` is { speed, topSpeed, distanceM }; `rivals` is
   * [{ id, distanceM, speed, finished, side }]. Returns the engine frame.
   */
  update(seconds, player, rivals = []) {
    if (this.stopped) return this.lastFrame;
    const frame = this.model.step(seconds, player.speed, player.topSpeed);
    this.lastFrame = frame;
    const profile = this.profile;
    const now = this.context.currentTime;

    // A little unevenness at idle, gone by mid revs: an engine at rest is never perfectly steady.
    const wobble = 1 + 0.012 * (1 - frame.rpmShare) * Math.sin((now - this.startedAt) * 19.5);
    const firing = frame.firing * wobble;
    this.set(this.main.frequency, firing);
    this.set(this.twin.frequency, firing * 1.006);
    this.set(this.sub.frequency, firing * profile.subRatio);
    this.set(this.subGain.gain, profile.sub * (1 - 0.45 * frame.rpmShare));

    const open = 0.3 + 0.7 * frame.throttle;
    this.set(this.tone.frequency, profile.dark + profile.bright * open * (0.3 + 0.7 * frame.rpmShare));
    this.set(this.formant.frequency, profile.formant * (0.85 + 0.5 * frame.rpmShare));
    const level = MIX.engineIdle + (MIX.engineFull - MIX.engineIdle) * (0.6 * frame.throttle + 0.4 * frame.rpmShare * (0.5 + 0.5 * frame.throttle));
    this.set(this.engineGain.gain, profile.trim * level);

    this.set(this.chugDepth.gain, MIX.chug * profile.trim * (1 - Math.min(1, frame.rpmShare * 2.5)) ** 2, 0.08);
    this.set(this.chugFilter.frequency, Math.max(480, profile.formant * 1.3));
    this.set(this.intakeFilter.frequency, 500 + 2300 * frame.rpmShare);
    this.set(this.intakeGain.gain, MIX.intake * profile.intake * frame.load);
    const roll = Math.min(1, frame.speedShare);
    this.set(this.roadFilter.frequency, 220 + 520 * roll);
    this.set(this.roadGain.gain, MIX.road * roll ** 1.4, 0.08);
    this.set(this.windGain.gain, MIX.wind * roll ** 2.6, 0.08);

    if (this.whistle) {
      this.set(this.whistle.frequency, 2300 + 5200 * frame.turbo, 0.06);
      this.set(this.whistleGain.gain, MIX.turbo * profile.turbo * frame.turbo ** 2, 0.06);
    }

    if (frame.shifted !== 0) this.thump(frame.shifted > 0 ? 82 : 96);
    if (frame.blowOff) this.burst({ type: "bandpass", from: 3400, to: 1800, q: 1.1, level: MIX.blowOff * profile.turbo, attack: 0.008, seconds: 0.3 });
    if (frame.crackle) this.crackle(profile.crackle);

    const heard = rivalMix({ distanceM: player.distanceM ?? 0, speed: frame.speed }, rivals);
    this.rivals.forEach((voice, index) => {
      const rival = heard[index];
      if (!rival) return this.set(voice.gain.gain, 0.0001, 0.12);
      const share = Math.min(1, rival.speed / Math.max(1, player.topSpeed));
      this.set(voice.oscillator.frequency, (46 + 150 * share) * rival.doppler, 0.06);
      this.set(voice.filter.frequency, 420 + 900 * share, 0.06);
      this.set(voice.gain.gain, MIX.rival * rival.level * 0.4, 0.1);
      if (voice.pan) this.set(voice.pan.pan, rival.pan, 0.12);
    });
    return frame;
  }

  /** A short filtered-noise sound: scrub, blow-off, a pass, the finish line. */
  burst({ type, from, to, q, level, attack, seconds, pan = null, delay = 0 }) {
    if (this.stopped || this.oneShots >= MAX_ONE_SHOTS) return;
    const context = this.context;
    const start = context.currentTime + delay;
    const source = context.createBufferSource();
    source.buffer = this.noise;
    const filter = this.filter(type, from, q);
    filter.frequency.setValueAtTime(from, start);
    filter.frequency.exponentialRampToValueAtTime(Math.max(40, to), start + seconds);
    const gain = this.gain(0.0001);
    gain.gain.setValueAtTime(0.0001, start);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, level), start + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, start + seconds);
    source.connect(filter).connect(gain);
    let last = gain;
    if (pan && typeof context.createStereoPanner === "function") {
      const panner = context.createStereoPanner();
      panner.pan.setValueAtTime(pan[0], start);
      panner.pan.linearRampToValueAtTime(pan[1], start + seconds);
      gain.connect(panner);
      last = panner;
    }
    last.connect(this.bus);
    this.oneShots += 1;
    source.addEventListener("ended", () => {
      this.oneShots = Math.max(0, this.oneShots - 1);
      last.disconnect();
    });
    // A different stretch of the noise each time, so repeats do not sound stamped out.
    source.start(start, (this.random() * (NOISE_SECONDS - seconds - 0.05)) || 0, seconds + 0.04);
  }

  /** The dull knock of a gear going in. */
  thump(frequency) {
    if (this.stopped || this.oneShots >= MAX_ONE_SHOTS) return;
    const context = this.context;
    const now = context.currentTime;
    const oscillator = context.createOscillator();
    oscillator.type = "sine";
    oscillator.frequency.setValueAtTime(frequency * 1.6, now);
    oscillator.frequency.exponentialRampToValueAtTime(frequency, now + 0.07);
    const gain = this.gain(0.0001);
    gain.gain.setValueAtTime(0.0001, now);
    gain.gain.exponentialRampToValueAtTime(MIX.shift, now + 0.008);
    gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.11);
    oscillator.connect(gain).connect(this.bus);
    this.oneShots += 1;
    oscillator.addEventListener("ended", () => {
      this.oneShots = Math.max(0, this.oneShots - 1);
      gain.disconnect();
    });
    oscillator.start(now);
    oscillator.stop(now + 0.14);
  }

  /** Two to four small pops in the exhaust, spread over a third of a second. */
  crackle(amount) {
    const pops = 2 + Math.floor(this.random() * 3);
    for (let index = 0; index < pops; index += 1) {
      this.burst({ type: "bandpass", from: 700 + this.random() * 500, to: 260, q: 1.6, level: MIX.crackle * amount * (0.6 + 0.4 * this.random()), attack: 0.004, seconds: 0.05, delay: 0.05 + index * (0.06 + this.random() * 0.05) });
    }
  }

  /**
   * A car goes past. `gained` true: the player overtakes (the other car falls
   * away behind); false: the player is overtaken (it pulls away ahead).
   */
  pass(gained, side = 1) {
    this.burst({
      type: "bandpass",
      from: gained ? 2000 : 700,
      to: gained ? 520 : 1700,
      q: 0.7,
      level: MIX.pass * (gained ? 1 : 0.7),
      attack: 0.09,
      seconds: 0.5,
      pan: [side * (gained ? 0.15 : 0.5), side * (gained ? 0.5 : 0.15)]
    });
  }

  /** Crossing the line: the air of the gantry going overhead. */
  finishLine() {
    this.burst({ type: "bandpass", from: 3200, to: 380, q: 0.8, level: MIX.finish, attack: 0.06, seconds: 0.9 });
  }

  /** Fade out and release every node. Safe to call twice. */
  stop(fadeSeconds = 0.25) {
    if (this.stopped) return;
    this.stopped = true;
    const now = this.context.currentTime;
    try {
      this.bus.gain.cancelScheduledValues(now);
      this.bus.gain.setTargetAtTime(0.0001, now, fadeSeconds / 4);
      for (const source of this.sources) source.stop(now + fadeSeconds + 0.05);
    } catch {
      /* already stopped */
    }
    const bus = this.bus;
    const release = () => {
      try {
        bus.disconnect();
      } catch {
        /* already released */
      }
    };
    if (this.sources[0]) this.sources[0].addEventListener("ended", release);
    else release();
    this.sources = [];
  }
}
